    WalletController_getTransactions: {
        parameters: {
            query?: {
                cursor?: string;
                sort?: "asc" | "desc";
                /** @description Inclusive exact IRR transaction magnitude upper bound, regardless of credit/debit sign */
                max?: string;
                /** @description Inclusive exact IRR transaction magnitude lower bound, regardless of credit/debit sign */
                min?: string;
                /** @description Literal transaction ID, public reference/description or original bank receipt bank/reference substring, up to 120 characters */
                q?: string;
                /** @description Exclusive ISO timestamp; cannot be combined with the legacy inclusive to bound */
                until?: string;
                /** @description Inclusive ISO timestamp */
                to?: string;
                /** @description Inclusive ISO timestamp */
                from?: string;
                state?: "Pending" | "Reserved" | "Completed" | "Failed" | "Rejected" | "Released" | "Reversed";
                type?: "topup" | "payment" | "refund" | "reservation" | "release" | "reversal" | "compensating";
                /** @description 1–100, default 50 */
                limit?: number;
            };
            header?: never;
            path: {
                profileId: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Wallet history; signed IRR amounts are exact decimal strings. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        nextCursor: string | null;
                        transactions: {
                            /** @example 9007199254740993 */
                            amount: string;
                            /** @description Original bank receipt details only; settlement credits omit this field. */
                            bankReceipt?: {
                                bankName: string | null;
                                customerNote: string | null;
                                payerReference: string | null;
                                /** Format: date */
                                paymentDate: string | null;
                                rejectionReason: string | null;
                                timeline: {
                                    /** @enum {string|null} */
                                    awaiting: "review" | "second_approval" | null;
                                    events: {
                                        /** Format: date-time */
                                        occurredAt: string | null;
                                        /** @enum {string} */
                                        state: "submitted" | "approval_requested" | "confirmed" | "rejected";
                                    }[];
                                };
                            };
                            /** Format: date-time */
                            createdAt: string;
                            description: string | null;
                            /** Format: uuid */
                            id: string;
                            refId: string | null;
                            state: string;
                            type: string;
                        }[];
                    };
                };
            };
        };
    };
